import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Sulfides","description":"","frontmatter":{"title":"Sulfides","mineralGroup":"sulfides"},"headers":[],"relativePath":"classification/mineral-groups/sulfides.md","filePath":"classification/mineral-groups/sulfides.md","lastUpdated":1790876393000}'),s={name:"classification/mineral-groups/sulfides.md"};function l(n,e,o,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="sulfides" tabindex="-1">Sulfides <a class="header-anchor" href="#sulfides" aria-label="Permalink to &quot;Sulfides&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Sulfides are notable for their optical effects and metallic luster:</p><ul><li><strong>Pyrite</strong> (FeS₂): &quot;fool&#39;s gold,&quot; cubic, often used ornamentally</li><li><strong>Sphalerite</strong> (ZnS): very high dispersion (0.156), exceeds diamond</li><li><strong>Galena</strong> (PbS): heavy and soft (Mohs 2.5), rarely gem-quality</li><li><strong>Cinnabar</strong> (HgS): deep red, mineralogically important</li></ul><h2 id="formula-class" tabindex="-1">Formula Class <a class="header-anchor" href="#formula-class" aria-label="Permalink to &quot;Formula Class&quot;">​</a></h2><p>M_xS_y (with S²⁻)</p><h2 id="crystal-structure" tabindex="-1">Crystal Structure <a class="header-anchor" href="#crystal-structure" aria-label="Permalink to &quot;Crystal Structure&quot;">​</a></h2><p>Metal cations bond with S²⁻ via ionic or covalent interactions. Common structures: NaCl-type (galena), sphalerite-type (ZnS tetrahedral coordination), pyrite-type (FeS₂ with dumbbell S₂²⁻ units).</p><h2 id="representative-gem-species" tabindex="-1">Representative Gem Species <a class="header-anchor" href="#representative-gem-species" aria-label="Permalink to &quot;Representative Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Formula</th><th>Subgroup</th></tr></thead><tbody><tr><td>Pyrite / 黄铁矿</td><td>FeS₂</td><td>pyrite</td></tr><tr><td>Sphalerite / 闪锌矿</td><td>ZnS</td><td>sphalerite</td></tr></tbody></table><p><em>See the <a href="./intro.html">mineral group overview</a>.</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA: Gem Species, Varieties, and Groups</a><span>Relationships among mineral species, gem varieties, and mineral groups</span><small>Open source ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat mineral database</a><span>Mineral names, chemistry, and classification lookup</span><small>Open source ↗</small></li></ul></aside>',12)])])}const h=a(s,[["render",l]]);export{m as __pageData,h as default};
